.darma-loader-darma-b14-xylophone-bars { --accent: var(--loader-color, #0ea5e9); --accent-2: var(--loader-secondary-color, #f43f5e); width: var(--loader-size, 120px); height: calc(var(--loader-size, 120px) * .68); position: relative; display: flex; flex-direction: column; justify-content: space-between; padding: 8% 0; }
.darma-loader-darma-b14-xylophone-bars::after { content: ''; position: absolute; left: 2%; top: 4%; width: 96%; height: 92%; border-radius: 4px; background: linear-gradient(90deg, color-mix(in srgb, #000 28%, var(--accent-2)) 0 calc(var(--loader-size, 120px) * .022), transparent calc(var(--loader-size, 120px) * .022)); }
.darma-loader-darma-b14-xylophone-bars span { position: relative; z-index: 2; height: 14%; margin-left: 5%; border-radius: 3px; transform-origin: left center; background: linear-gradient(90deg, var(--accent), var(--accent-2)); box-shadow: 0 1px 2px rgba(15, 23, 42, .25); animation: darma-loader-darma-b14-xylophone-bars-ring-bar calc(var(--loader-speed, 1s) * 2.4) ease-out infinite; }
.darma-loader-darma-b14-xylophone-bars span:nth-child(1) { width: 88%; }
.darma-loader-darma-b14-xylophone-bars span:nth-child(2) { width: 76%; animation-delay: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b14-xylophone-bars span:nth-child(3) { width: 64%; animation-delay: calc(var(--loader-speed, 1s) * 1.2); }
.darma-loader-darma-b14-xylophone-bars span:nth-child(4) { width: 52%; animation-delay: calc(var(--loader-speed, 1s) * 1.8); }
.darma-loader-darma-b14-xylophone-bars .darma-loader-darma-b14-xylophone-bars__mallet { position: absolute; z-index: 3; top: 0; left: 26%; width: calc(var(--loader-size, 120px) * .035); height: 26%; border-radius: 2px; background: linear-gradient(90deg, #f1f5f9, #64748b); animation: darma-loader-darma-b14-xylophone-bars-mallet-hit calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b14-xylophone-bars .darma-loader-darma-b14-xylophone-bars__mallet::after { content: ''; position: absolute; bottom: calc(var(--loader-size, 120px) * -.05); left: calc(var(--loader-size, 120px) * -.033); width: calc(var(--loader-size, 120px) * .1); height: calc(var(--loader-size, 120px) * .1); border-radius: 50%; background: radial-gradient(circle at 36% 32%, color-mix(in srgb, #fff 34%, var(--accent-2)), color-mix(in srgb, #000 24%, var(--accent-2))); }
@keyframes darma-loader-darma-b14-xylophone-bars-ring-bar { 0%, 100% { transform: scaleY(1); filter: brightness(1); } 6% { transform: scaleY(1.5); filter: brightness(1.4); } 20% { transform: scaleY(1); filter: brightness(1); } }
@keyframes darma-loader-darma-b14-xylophone-bars-mallet-hit { 0% { transform: translate(0, 6%); } 6% { transform: translate(0, 30%); } 16% { transform: translate(-2%, 10%); } 25% { transform: translate(-4%, 92%); } 31% { transform: translate(-4%, 116%); } 41% { transform: translate(-6%, 96%); } 50% { transform: translate(-8%, 178%); } 56% { transform: translate(-8%, 202%); } 66% { transform: translate(-10%, 182%); } 75% { transform: translate(-12%, 264%); } 81% { transform: translate(-12%, 288%); } 91% { transform: translate(-6%, 150%); } 100% { transform: translate(0, 6%); } }

